<?php declare(strict_types=1); $this->layout('layouts/default',['title'=>$title,'currentPage'=>'media']); ?>
<section class="studio-page studio-media-page cms-workspace-page"><header class="knowledge-header"><div><p class="studio-eyebrow">ARQUIVOS</p><h2>Biblioteca de mídia</h2><p>Visualize, filtre e gerencie as imagens usadas pelo sistema.</p></div><div class="studio-actions"><details class="studio-upload-popover"><summary class="studio-btn primary"><?= studio_icon('upload') ?> Enviar imagem</summary><form method="post" enctype="multipart/form-data"><?= $this->csrf() ?><input type="hidden" name="action" value="upload"><label for="image">JPG, PNG, GIF ou WebP, até 8 MB</label><input id="image" type="file" name="image" accept="image/jpeg,image/png,image/gif,image/webp" required><button class="studio-btn primary">Enviar arquivo</button></form></details><span class="studio-btn"><?= (int)($pagination['total']??count($files)) ?> arquivos</span></div></header><nav class="support-knowledge-tabs cms-workspace-tabs" aria-label="Conteúdo do CMS"><a href="/studio/articles"><?= studio_icon('newspaper') ?> Artigos</a><a href="/studio/categories"><?= studio_icon('archive') ?> Categorias</a><a href="/studio/tags"><?= studio_icon('tag') ?> Tags</a><a class="active" href="/studio/media"><?= studio_icon('image') ?> Mídia</a><a href="/studio/trash"><?= studio_icon('trash') ?> Lixeira</a></nav>
