<div class="studio-media-grid"><?php if($files===[]):?><p class="studio-panel studio-empty">Nenhuma imagem enviada.</p><?php endif;?><?php foreach($files as $file):?><article class="studio-panel studio-media-card"><div class="studio-media-preview"><img src="/studio/media/file/<?= (int)$file['id'] ?>" alt="<?= $this->e($file['alt_text']??'') ?>"><span><?= (int)$file['usage_count']>0?'Em uso':'Livre' ?></span></div><div class="studio-media-meta"><h3><?= $this->e($file['name']) ?></h3><p><?= (int)$file['width'] ?> × <?= (int)$file['height'] ?> px</p></div><details class="studio-media-manage"><summary>Gerenciar imagem</summary><form method="post"><?= $this->csrf() ?><input type="hidden" name="action" value="metadata"><input type="hidden" name="id" value="<?= (int)$file['id'] ?>"><label><span>Texto alternativo</span><input name="alt_text" maxlength="255" value="<?= $this->e($file['alt_text']??'') ?>" placeholder="Descreva a imagem"></label><button>Salvar descrição</button></form><form class="studio-crop-form" method="post"><?= $this->csrf() ?><input type="hidden" name="action" value="crop"><input type="hidden" name="id" value="<?= (int)$file['id'] ?>"><?php foreach(['crop_x'=>'X','crop_y'=>'Y','crop_width'=>'Largura','crop_height'=>'Altura'] as $name=>$label):?><label><span><?= $label ?></span><input type="number" name="<?= $name ?>" min="0" value="<?= str_contains($name,'width')?(int)$file['width']:(str_contains($name,'height')?(int)$file['height']:0) ?>" required></label><?php endforeach;?><button>Criar cópia recortada</button></form><form method="post" data-confirm-submit="Excluir esta imagem?"><?= $this->csrf() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$file['id'] ?>"><button class="studio-danger-button"<?= (int)$file['usage_count']>0?' disabled title="Imagem em uso"':'' ?>><?= studio_icon('trash') ?> Excluir</button></form></details></article><?php endforeach;?></div>
<?php if(($pagination['totalPages']??1)>1): $query=['q'=>$search]; ?><nav class="studio-pagination" aria-label="Paginação da mídia"><span><?= (int)$pagination['total'] ?> arquivo(s) · Página <?= (int)$pagination['page'] ?> de <?= (int)$pagination['totalPages'] ?></span><div><?php if($pagination['page']>1): $query['page']=$pagination['page']-1; ?><a href="/studio/media?<?= $this->e(http_build_query($query)) ?>">Anterior</a><?php endif;?><?php if($pagination['page']<$pagination['totalPages']): $query['page']=$pagination['page']+1; ?><a href="/studio/media?<?= $this->e(http_build_query($query)) ?>">Próxima</a><?php endif;?></div></nav><?php endif;?>
